#include <condition_variable>
#include <iostream>
#include <mutex>
#include <queue>
#include <thread>

int main() {
    std::mutex mutex;
    std::condition_variable ready;
    std::queue<int> queue;
    bool done = false;
    std::jthread consumer([&] {
        std::unique_lock lock(mutex);
        ready.wait(lock, [&] { return done || !queue.empty(); });
        if (!queue.empty()) std::cout << queue.front() << '\n';
    });
    { std::lock_guard lock(mutex); queue.push(42); done = true; }
    ready.notify_one();
}
